const e=[{title:"What is MLOps?",subtitle:"From Notebook to Owned Service",bullets:[{text:"MLOps applies DevOps discipline to data, models, and experiments.",icon:"monitoring"},{text:"Goal: reproducible training, safe deployment, and continuous monitoring.",icon:"train"},{text:"Bridges data science, engineering, and operations teams.",icon:"regression"}],speakerNote:"Ask who has had a model 'work in Jupyter' but fail in production.",titleIcon:"monitoring",conceptAnimation:"mlops-lifecycle"},{title:"ML System Components",bullets:[{text:"Data pipelines — ingestion, validation, feature stores.",icon:"test"},{text:"Training pipelines — experiment tracking, model registry.",icon:"train"},{text:"Serving — APIs, batch scoring, edge deployment.",icon:"monitoring"},{text:"Monitoring — data drift, concept drift, performance decay.",icon:"monitoring"}],speakerNote:"Map components to tools trainees may already know (Git, Docker, cloud).",titleIcon:"idea"},{title:"Reproducibility",table:{headers:["Artifact","Why version it"],rows:[["Code + config","Recreate training exactly"],["Training data snapshot","Audit and debug drift"],["Model weights","Rollback and compare"],["Environment","Same dependencies in train and serve"]]},speakerNote:"Without data versioning, you cannot explain last month's metric drop.",titleIcon:"idea"},{title:"Experiment Tracking",bullets:[{text:"Log parameters, metrics, artifacts, and git SHA per run.",icon:"metric"},{text:"Compare runs side-by-side before promoting a model.",icon:"model"},{text:"Tools: MLflow, Weights & Biases, Neptune, cloud-native trackers.",icon:"regression"}],speakerNote:"Show one MLflow UI screenshot if available.",titleIcon:"idea"},{title:"Model Registry & Promotion",bullets:[{text:"Stages: staging → production → archived.",icon:"model"},{text:"Promotion gates: metric thresholds, bias checks, sign-off.",icon:"metric"},{text:"Never deploy straight from a laptop without registry metadata.",icon:"monitoring"}],speakerNote:"Tie registry to change management in enterprise IT.",titleIcon:"model"},{title:"CI/CD for Machine Learning",bullets:[{text:"CI: unit tests + data/schema validation + training smoke tests.",icon:"train"},{text:"CD: deploy container or endpoint when registry stage changes.",icon:"monitoring"},{text:"Feature pipelines may need separate release cadence from models.",icon:"monitoring"}],speakerNote:"Contrast app CI (code only) vs ML CI (data + model).",titleIcon:"monitoring",illustration:"mlops-loop"},{title:"Data Drift vs Concept Drift",table:{headers:["Type","Definition","Example signal"],rows:[["Data drift","Input distribution changes","New user demographics"],["Concept drift","P(y|x) changes","Fraud patterns evolve"],["Label drift","Labeling policy changes","Stricter QA on positives"]]},speakerNote:"Monitoring without action is useless — define playbooks per drift type.",titleIcon:"data"},{title:"Monitoring in Production",bullets:[{text:"Track latency, error rate, throughput at the serving layer.",icon:"neural-net"},{text:"Track prediction distribution and feature statistics over time.",icon:"feature"},{text:"Alert on SLA breaches and statistical tests vs training baseline.",icon:"train"}],speakerNote:"Golden rule: monitor what you would check the morning after launch.",titleIcon:"monitoring"},{title:"Feature Stores",body:"Centralize features for training and serving to prevent train-serve skew.",bullets:[{text:"Same feature definitions online and offline.",icon:"feature"},{text:"Point-in-time correctness for historical training sets.",icon:"train"},{text:"Reuse across teams — reduces duplicated ETL.",icon:"idea"}],speakerNote:"Train-serve skew is a top cause of silent production degradation.",titleIcon:"idea"},{title:"Deployment Patterns",bullets:[{text:"Batch scoring for reports and nightly jobs.",icon:"monitoring"},{text:"Real-time REST/gRPC for interactive products.",icon:"monitoring"},{text:"Shadow / canary deploys to compare new model safely.",icon:"monitoring"}],speakerNote:"Canary: route 5% traffic, compare business metrics before full cutover.",titleIcon:"monitoring"},{title:"Mini Lab — MLflow-style Run Log",bullets:[{text:"Log hyperparameters and evaluation metrics per training run.",icon:"train"},{text:"Tag runs with git SHA and data version for auditability.",icon:"data"},{text:"Push artifacts to MLflow, W&B, or your cloud tracker in production.",icon:"idea"}],speakerNote:"Emphasize tags for audit — who trained, on what data, when.",titleIcon:"idea"},{title:"Capstone — Your MLOps Roadmap",bullets:[{text:"Pick one model from the bootcamp and draw its production path.",icon:"model"},{text:"List 3 metrics you would monitor week one after launch.",icon:"monitoring"},{text:"Identify the single biggest reproducibility gap in your current workflow.",icon:"monitoring"}],speakerNote:"Close bootcamp — collect roadmaps as exit ticket; celebrate completion.",titleIcon:"monitoring",conceptAnimation:"mlops-lifecycle"}];export{e as slides};
